<script>(function(){var b=document.getElementById('menuToggle'),n=document.getElementById('siteNavigation'),o=document.getElementById('menuOverlay');if(!b||!n||!o)return;function close(){n.classList.remove('is-open');o.classList.remove('is-open');document.body.classList.remove('menu-open');b.textContent='☰';b.setAttribute('aria-expanded','false')}b.addEventListener('click',function(){var open=!n.classList.contains('is-open');n.classList.toggle('is-open',open);o.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);b.textContent=open?'×':'☰';b.setAttribute('aria-expanded',open?'true':'false')});o.addEventListener('click',close);n.addEventListener('click',function(e){if(e.target.closest('a'))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(window.innerWidth>600)close()})})();</script></body></html>